parameters.jsCode:
const data = items[0].json.data.recentSubmissionList;
if (!data || data.length === 0) {
  return [{ json: { message: "No recent submissions found today! Keep grinding!" } }];
}

const latest = data[0];
const submissionTime = new Date(latest.timestamp * 1000);
const isToday = submissionTime.toDateString() === new Date().toDateString();

return [{
  json: {
    title: latest.title,
    status: latest.statusDisplay,
    language: latest.lang,
    link: `https://leetcode.com/problems/${latest.titleSlug}/`,
    solvedToday: isToday,
    message: isToday 
      ? `🔥 LeetCode Update! Solved: ${latest.title} (${latest.lang}) with status: ${latest.statusDisplay}!` 
      : "⚠️ Reminder: You hasn't solved a LeetCode problem yet today! Go protect your streak!"
  }
}];
